select jsonb_build_object('observed_at',current_timestamp,'guard_functions',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'definition',pg_get_functiondef(p.oid))) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname='core' and p.proname='guard_client_user_fields') or (n.nspname='public' and p.proname in ('is_admin','is_admin_or_trainer','get_user_role'))),'gamification_triggers',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid))) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='gamification' and c.relname in ('xp_ledger','login_rewards','currency_wallets','currency_ledger') and not t.tgisinternal),'gamification_constraints',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',k.conname,'definition',pg_get_constraintdef(k.oid))) from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='gamification' and c.relname in ('xp_ledger','login_rewards','currency_wallets','currency_ledger'))) as inspection;
